CREATE OR REPLACE FUNCTION public.bix_growth_excluded(p_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ WITH RECURSIVE ancestors AS (SELECT p_user AS uid, ARRAY[p_user] AS path UNION ALL SELECT r.referred_by, a.path || r.referred_by FROM ancestors a JOIN public.referral_codes r ON r.user_id=a.uid WHERE r.referred_by IS NOT NULL AND NOT r.referred_by=ANY(a.path)) SELECT EXISTS(SELECT 1 FROM ancestors a JOIN public.user_roles u ON u.user_id=a.uid WHERE u.role='reviewer') $$;
REVOKE ALL ON FUNCTION public.bix_growth_excluded(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.bix_growth_excluded(uuid) TO service_role;
CREATE TABLE public.bix_growth_control (id integer PRIMARY KEY DEFAULT 1 CHECK(id=1), activity_enabled boolean NOT NULL DEFAULT true, radar_enabled boolean NOT NULL DEFAULT true, flash_title text NOT NULL DEFAULT 'BIXLINK community event', flash_enabled boolean NOT NULL DEFAULT false, flash_ends_at timestamptz, circuit_enabled boolean NOT NULL DEFAULT true, threshold_usd numeric NOT NULL DEFAULT 5000 CHECK(threshold_usd>0), window_minutes integer NOT NULL DEFAULT 120 CHECK(window_minutes BETWEEN 1 AND 1440), frozen boolean NOT NULL DEFAULT false, freeze_reason text, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.bix_growth_control TO authenticated; GRANT ALL ON public.bix_growth_control TO service_role;
ALTER TABLE public.bix_growth_control ENABLE ROW LEVEL SECURITY;
CREATE POLICY growth_owner ON public.bix_growth_control TO authenticated USING(public.is_bix_admin()) WITH CHECK(public.is_bix_admin());
CREATE OR REPLACE FUNCTION public.bix_growth_snapshot() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE c jsonb; events jsonb; BEGIN IF auth.uid() IS NOT NULL AND public.bix_growth_excluded(auth.uid()) THEN RETURN jsonb_build_object('eligible',false); END IF; SELECT to_jsonb(g) INTO c FROM public.bix_growth_control g WHERE id=1; c:=COALESCE(c,'{"activity_enabled":true,"radar_enabled":true,"flash_enabled":false,"circuit_enabled":true,"threshold_usd":5000,"window_minutes":120,"frozen":false,"flash_title":"BIXLINK community event"}'::jsonb); SELECT COALESCE(jsonb_agg(x),'[]'::jsonb) INTO events FROM (SELECT w.id, 'Verified deposit'::text AS kind, round(w.amount_usd,2) AS amount, w.verified_at AS at, 'BIX-' || left(r.code,0) || right(left(r.code,6),2) || '****' AS member FROM public.wallet_transactions w JOIN public.referral_codes r ON r.user_id=w.user_id WHERE w.type='deposit' AND w.status='approved' AND w.verified_at IS NOT NULL AND w.tx_hash IS NOT NULL AND NOT public.bix_growth_excluded(w.user_id) AND NOT EXISTS(SELECT 1 FROM public.bix_clone_accounts b WHERE b.user_id=w.user_id) AND NOT EXISTS(SELECT 1 FROM public.bix_leaders l WHERE l.user_id=w.user_id AND l.status='approved') ORDER BY w.verified_at DESC LIMIT 12) x; RETURN jsonb_build_object('eligible',true,'control',jsonb_build_object('activity_enabled',c->'activity_enabled','radar_enabled',c->'radar_enabled','flash_enabled',c->'flash_enabled','flash_title',c->'flash_title','flash_ends_at',c->'flash_ends_at','frozen',c->'frozen'),'events',CASE WHEN (c->>'activity_enabled')::boolean THEN events ELSE '[]'::jsonb END); END $$;
REVOKE ALL ON FUNCTION public.bix_growth_snapshot() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.bix_growth_snapshot() TO anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.bix_growth_radar() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; IF public.bix_growth_excluded(auth.uid()) OR EXISTS(SELECT 1 FROM public.bix_growth_control WHERE NOT radar_enabled) THEN RETURN '[]'::jsonb; END IF; SELECT COALESCE(jsonb_agg(x),'[]'::jsonb) INTO result FROM (SELECT r.code, p.full_name AS name, p.created_at AS joined_at, d.deposit_usd, s.last_activity, COALESCE(l.support_kind,'member') AS kind, COALESCE(l.virtual_usd*l.turnover_multiple,0) AS target, t.turnover FROM public.referral_codes r JOIN public.profiles p ON p.user_id=r.user_id LEFT JOIN public.bix_leaders l ON l.user_id=r.user_id AND l.status='approved' LEFT JOIN LATERAL (SELECT COALESCE(sum(amount_usd),0) deposit_usd FROM public.wallet_transactions WHERE user_id=r.user_id AND type='deposit' AND status='approved' AND verified_at IS NOT NULL AND tx_hash IS NOT NULL) d ON true LEFT JOIN LATERAL (SELECT GREATEST(p.created_at, max(created_at)) AS last_activity FROM public.wallet_transactions WHERE user_id=r.user_id) s ON true LEFT JOIN LATERAL (SELECT COALESCE(sum(st.amount_usd),0) turnover FROM public.stakes st JOIN public.referral_codes rc ON rc.user_id=st.user_id WHERE rc.referred_by=r.user_id AND st.status='active' AND NOT EXISTS(SELECT 1 FROM public.bix_clone_accounts b WHERE b.user_id=st.user_id)) t ON true WHERE r.referred_by=auth.uid() AND NOT public.bix_growth_excluded(r.user_id) AND NOT EXISTS(SELECT 1 FROM public.bix_clone_accounts b WHERE b.user_id=r.user_id) ORDER BY p.created_at DESC) x; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.bix_growth_radar() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.bix_growth_radar() TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.bix_growth_withdraw_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.bix_growth_control; total numeric; BEGIN IF NEW.type<>'withdraw' OR public.bix_growth_excluded(NEW.user_id) THEN RETURN NEW; END IF; PERFORM pg_advisory_xact_lock(hashtext('bix-growth-withdraw')); SELECT * INTO c FROM public.bix_growth_control WHERE id=1; IF COALESCE(c.frozen,false) AND (TG_OP='INSERT' OR NEW.status IS DISTINCT FROM OLD.status) AND NEW.status IN ('pending','approved') THEN RAISE EXCEPTION 'Withdrawal requests temporarily paused by Owner 1. Existing records are preserved.'; END IF; RETURN NEW; END $$;
CREATE TRIGGER bix_growth_withdraw_guard BEFORE INSERT OR UPDATE ON public.wallet_transactions FOR EACH ROW EXECUTE FUNCTION public.bix_growth_withdraw_guard();
CREATE OR REPLACE FUNCTION public.bix_growth_circuit_check() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.bix_growth_control; total numeric; BEGIN IF NEW.type<>'withdraw' OR NEW.status<>'pending' OR public.bix_growth_excluded(NEW.user_id) THEN RETURN NEW; END IF; PERFORM pg_advisory_xact_lock(hashtext('bix-growth-withdraw')); SELECT * INTO c FROM public.bix_growth_control WHERE id=1; IF NOT COALESCE(c.circuit_enabled,true) THEN RETURN NEW; END IF; SELECT COALESCE(sum(amount_usd),0) INTO total FROM public.wallet_transactions WHERE type='withdraw' AND status='pending' AND created_at>=now()-make_interval(mins=>COALESCE(c.window_minutes,120)) AND NOT public.bix_growth_excluded(user_id); IF total>COALESCE(c.threshold_usd,5000) THEN INSERT INTO public.bix_growth_control(id,frozen,freeze_reason) VALUES(1,true,'Automatic queue threshold exceeded') ON CONFLICT(id) DO UPDATE SET frozen=true,freeze_reason='Automatic queue threshold exceeded',updated_at=now(); END IF; RETURN NEW; END $$;
CREATE TRIGGER bix_growth_circuit_check AFTER INSERT OR UPDATE ON public.wallet_transactions FOR EACH ROW EXECUTE FUNCTION public.bix_growth_circuit_check();